    lp2_f_eff = fm1_key_apply(lp2_f, fm1_key_add(f2_ks_k_x, 0), 0, 65535);
    lp2_fc = fm1_clamp16(lp2_f_eff + fm1_q16_mul(lp2_fenv_depth, 0));
